<script setup lang="ts">import {ref} from 'vue';import axios from 'axios';const props=defineProps<{id:string}>();const student=ref('00000000-0000-0000-0000-000000000011');const score=ref(0);const comment=ref('');const version=ref(0);const status=ref('');async function save(){await axios.put(`/api/v1/teacher/exams/${props.id}/reviews/${student.value}`,{score:score.value,comment:comment.value,version:version.value});version.value++;status.value='Saved'} </script>
<template><main><h1>Manual Review</h1><label>Student ID <input v-model="student"></label><section><h2>Source snapshot</h2><pre>Load immutable submission source through the review API.</pre></section><label>Final score <input type="number" v-model.number="score" min="0"></label><textarea v-model="comment" placeholder="Teacher comment"></textarea><button @click="save">Save review</button><span>{{status}}</span></main></template><style scoped>main{padding:32px;display:grid;gap:12px;max-width:800px;font:16px system-ui}textarea{min-height:120px}button{width:140px;padding:9px}</style>
